import { createRequire } from 'module'
const require = createRequire('D:/repository/苏住房G/package.json')
const LIB = 'D:/repository/苏住房G/e2e/std-evaluation/lib/std-eval-lib.cjs'
const { createSuite } = require(LIB)
const suite = createSuite({ name: 'remote-check-6582', task: 'verify', dir: 'remote-check-6582' })
suite.run(async ({ page, ui, step, note }) => {
  const p = await page()
  await ui.login(p)
  const base = (process.env.E2E_BASE_URL || '').replace(/\/$/, '')
  await step('home-remote', async () => {
    await p.goto(`${base}/#/index`, { waitUntil: 'domcontentloaded' })
    await p.waitForTimeout(9000)
    const m = await p.evaluate(() => {
      const r=(el)=>el?{w:Math.round(el.getBoundingClientRect().width),h:Math.round(el.getBoundingClientRect().height)}:null
      const w=document.querySelector('.kd__icon-wrap'), i=document.querySelector('.kd__icon'), b=document.querySelector('.kd__box')
      // 抓取 scoped style 里 kd__icon-wrap 的规则文本
      let ruleText=''
      for(const s of document.styleSheets){ try{ for(const rr of s.cssRules||[]){ if(rr.selectorText&&rr.selectorText.includes('kd__icon-wrap')&&rr.style&&rr.style.width){ ruleText += rr.selectorText+'{width:'+rr.style.width} } }catch(e){} }
      return {wrap:r(w), icon:r(i), box:r(b), ruleText}
    })
    console.log('REMOTE METRICS:', JSON.stringify(m))
    await p.screenshot({ path: 'e2e/artifacts/fix-6582/remote-now.png', fullPage: true }).catch(e=>console.log('shot fail',e.message))
    console.log('URL:', p.url())
  })
  note('done')
})

