const require = createRequire('D:/repository/苏住房G/package.json')
const LIB = 'D:/repository/苏住房G/e2e/std-evaluation/lib/std-eval-lib.cjs'
const { createSuite } = require(LIB)
const suite = createSuite({ name: 'measure-6582', task: 'verify', dir: 'measure-6582' })
suite.run(async ({ page, ui, step, note }) => {
  const p = await page()
  await ui.login(p)
  const base = (process.env.E2E_BASE_URL || 'http://127.0.0.1:8101').replace(/\/$/, '')
  await step('measure', async () => {
    await p.goto(`${base}/#/index`, { waitUntil: 'domcontentloaded' })
    await p.waitForTimeout(8000)
    const data = await p.evaluate(() => {
      const rows = Array.from(document.querySelectorAll('.kd__row'))
      const out = []
      rows.forEach((row, ri) => {
        const cards = Array.from(row.querySelectorAll('.kd__card'))
        const cardInfo = cards.map((card, ci) => {
          const groups = Array.from(card.querySelectorAll('.kd__boxes'))
          return {
            card: ci,
            cardH: Math.round(card.getBoundingClientRect().height),
            cardTop: Math.round(card.getBoundingClientRect().top),
            groups: groups.map(g => ({
              cls: g.className,
              gH: Math.round(g.getBoundingClientRect().height),
              boxes: Array.from(g.querySelectorAll('.kd__box')).map(b => ({ h: Math.round(b.getBoundingClientRect().height), top: Math.round(b.getBoundingClientRect().top), bottom: Math.round(b.getBoundingClientRect().bottom) }))
            }))
          }
        })
        out.push({ row: ri, cards: cardInfo })
      })
      return out
    })
    console.log(JSON.stringify(data, null, 1))
  })
  note('done')
})

